# Medical Spelling: practice tests and flashcards.
# The official Round One test gives a definition and asks for the correctly spelled term
# (Taber's is the reference). There is no topic-weighted test plan.
# Wrong options are deliberate misspellings; none is a valid British or variant spelling.

TOPICS = {"S": "Spelling"}


def W(definition, word, wrong, tip):
    return ("S", definition, word, wrong, tip)


